package vn.edu.eaut.lab7.repository; import vn.edu.eaut.lab7.model.*; import java.util.*; import java.util.stream.*; public class SanPhamRepository { private static final List<SanPham> data=new ArrayList<>(List.of(new SanPham(1,"SP001","Laptop Dell","Laptop học tập",15000000,10),new SanPham(2,"SP002","Chuột Logitech","Chuột không dây",500000,20))); private static int next=3; public List<SanPham> findAll(){return data;} public SanPham findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public void add(SanPham x){x.setId(next++);data.add(x);} public void update(SanPham x){SanPham o=findById(x.getId());if(o!=null){o.setMa(x.getMa());o.setTen(x.getTen());o.setMoTa(x.getMoTa());o.setGia(x.getGia());o.setSoLuong(x.getSoLuong());}} public void delete(int id){data.removeIf(x->x.getId()==id);} public List<SanPham> search(String k){if(k==null||k.isBlank())return data;String q=k.toLowerCase();return data.stream().filter(x->x.getMa().toLowerCase().contains(q)||x.getTen().toLowerCase().contains(q)).collect(Collectors.toList());} }